using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 LedgerContract Ledger=>game.World.Changes.Ledger??=new();
 string ScoutName(int i)=>ResidentNames[i][3];
 void BeginSettlementStory(int i){var t=Town(i);if(t.Fallen||i==3||t.StoryStage!=0)return;SettlementMissionPoint(t);t.StoryStage=1;t.StoryDue=game.World.Changes.Time+1800;t.StoryResult=ScoutName(i)+" missed the supply run. Find them within 30 active minutes, or they will die. The marker is on your map.";game.WorldDecision("settlement/start/"+i,t.StoryResult);}
 void AdvanceSettlement(SurvivorSettlement t,int stage,int growth,string outcome){t.StoryStage=stage;t.Development=Math.Clamp(t.Development+growth,0,3);t.StoryDue=stage<4?game.World.Changes.Time+3600:0;t.StoryResult=t.LastEvent=outcome;game.WorldDecision($"settlement/{t.Index}/{stage}",outcome);}
 bool PaySettlementCost(int food,int water,int timber,int alloy,int electronics,int fuel=0){if(game.Life.Food<food||game.Craft.Water<water||game.Craft.Materials[0]<timber||game.Craft.Materials[4]<alloy||game.Craft.Materials[5]<electronics||game.Craft.Fuel<fuel){game.Notice=$"Needs {food} food, {water} clean water, {timber} timber, {alloy} alloy, {electronics} electronics, {fuel} fuel";return false;}game.Life.Food-=food;game.Craft.Water-=water;game.Craft.Materials[0]-=timber;game.Craft.Materials[4]-=alloy;game.Craft.Materials[5]-=electronics;game.Craft.Fuel-=fuel;return true;}
 bool SettlementCampaignAction(int i,string op){if(!op.StartsWith("quest:")&&!op.StartsWith("trade:"))return false;var t=Town(i);if(t==null||t.Fallen){game.Notice="This community is gone. Its choices cannot be reset.";return true;}if(op.StartsWith("trade:")){SettlementTrade(t,op.Substring(6));return true;}
  if(i==3){LedgerAction(op.Substring(6));return true;}if(t.Trust<0||Standing("town/"+i).Value<0){game.Notice="They need you to rebuild trust before accepting help.";return true;}string choice=op.Substring(6);if(choice=="warn"){WarnLedgerTarget(i);game.Notice=Ledger.Outcome;return true;}bool changed=false;
  if(t.StoryStage==1&&choice=="abandon"){t.DeadResidents|=8;AdvanceSettlement(t,2,0,$"{ScoutName(i)} never came home. The settlement buries an empty coat; its supply project continues with fewer hands.");RememberTown(i,-8,t.StoryResult);changed=true;}
  else if(t.StoryStage==2&&choice is "care" or "fortify"){
   int wood=choice=="care"?16:24,alloy=choice=="care"?4+i*4:10+i*5,water=choice=="care"?4:0;if(!PaySettlementCost(0,water,wood,alloy,i))return true;
   t.Foundation=choice;t.WaterFixed=choice=="care"||t.WaterFixed;t.ClinicFixed=i==2&&choice=="care"||t.ClinicFixed;AdvanceSettlement(t,3,1,choice=="care"?new[]{"Iris restores irrigation and seed beds. Families can grow food again.","Nia opens a powered recovery bay beside Gus's workshop.","Ada establishes a surgical station. Quarantined patients receive treatment."}[i]:new[]{"Jules builds a watch line. The gardens remain smaller, but raids meet stronger defenses.","Len seals the yard behind reinforced gates. The workshops now prioritize weapons.","Rook establishes a defended quarantine perimeter. Some rooms become armories."}[i]);RememberTown(i,10,t.StoryResult);changed=true;
  }else if(t.StoryStage==3&&choice is "commons" or "exclusive" or "cashout"){
   if(choice=="commons"){if(!PaySettlementCost(6,4,0,0,0))return true;t.Policy="commons";t.Food+=6;t.Water+=4;var other=game.World.Changes.Settlements.FirstOrDefault(s=>s.Index!=i&&s.Index<3&&!s.Fallen);if(other!=null){other.Food+=3;other.Water+=3;}AdvanceSettlement(t,4,1,"A mutual-aid route opens. Their best civilian equipment is traded to people they trust. The next community receives a convoy.");RememberTown(i,12,t.StoryResult);}
   else if(choice=="exclusive"){if(!PaySettlementCost(0,0,0,8+i*4,2+i))return true;t.Policy="exclusive";AdvanceSettlement(t,4,1,"The stores become an exclusive arsenal. Better weapons arrive, but civilian relief stock stays limited.");RememberTown(i,6,t.StoryResult);}
   else{t.Policy="stripped";game.Craft.Materials[4]+=8+i*4;game.Life.Food+=4;AdvanceSettlement(t,4,-1,"You took the project's final stock as payment. The settlement survives in decline; its top market will never open.");RememberTown(i,-20,t.StoryResult);}changed=true;
  }
  if(changed){game.Persist();game.Notice=t.StoryResult;}else game.Notice="That chapter or choice is no longer available.";return true;
 }
 void FailLedger(string outcome){if(Ledger.State is "enemy" or "completed")return;Ledger.State="enemy";Ledger.Outcome=outcome;Town(3).Trust=-100;RememberTown(3,-50,outcome);ScheduleLedgerRaid();game.WorldDecision("ledger/betrayal",outcome);game.Persist();}
 void ScheduleLedgerRaid(){if(Ledger.RaidScheduled)return;Ledger.RaidScheduled=true;LocateLedgerCamp();Ledger.RaidDue=game.World.Changes.Time+180+game.ModulePower(2);Ledger.Outcome+=" The Black Ledger will send one armed retaliation party to your camp. Three active minutes to prepare; it fights when the camp is occupied.";}
 void LedgerAction(string op){
  if(op=="begin"&&Ledger.State=="unmet"){if(game.Craft.UnlockedTier<4){game.Notice="Black Ledger contracts require tier-four discovery.";return;}SettlementMissionPoint(Town(3));Ledger.Owner=CommunityOwner;Ledger.State="debt";Ledger.Due=game.World.Changes.Time+1800;Ledger.Outcome="VOSS: Recover the seized shipment. Thirty active minutes. Once you take our contract, failure makes you a target. Your camp is collateral.";}
  else if(op=="deliver"&&Ledger.State=="debt"&&Ledger.CacheTaken){Ledger.State="offer";Ledger.Due=game.World.Changes.Time+3600;Town(3).Development=1;Town(3).Food+=12;Town(3).Water+=12;Town(3).Trust+=15;RememberTown(3,15,"You returned a shipment taken from other survivors.");game.Craft.Materials[5]+=4;Ledger.Outcome="Mercer opens the city market. Voss offers a richer contract: erase an early settlement. Your history there determines how you get in. You have 60 active minutes to accept or break the order; ignoring it also brings retaliation.";}
  else if(op=="accept"&&Ledger.State=="offer"){var target=game.World.Changes.Settlements.Where(s=>s.Index<2&&!s.Fallen).OrderBy(s=>s.Index).FirstOrDefault();if(target==null){game.Notice="Both early communities are already gone. There is nobody left to betray.";return;}Ledger.Target=target.Index;Ledger.Route=Standing("town/"+target.Index).Value>=20?"infiltration":"assault";Ledger.State=Ledger.Route;Ledger.Due=game.World.Changes.Time+3600;Ledger.Outcome=$"Destroy {ExpeditionGame.SettlementNames[target.Index]} within 60 active minutes. Route locked: {Ledger.Route}. "+(Ledger.Route=="infiltration"?"They trust you. Disable their water and gate from inside, then ignite the stores. These actions will kill the adults who trusted you.":"They do not trust you. Enter by force and kill all four adult residents and their guard.")+" You may instead warn and fortify them, turning the Ledger against your own camp.";}
  else if(op=="refuse"&&Ledger.State is "debt" or "offer" or "assault" or "infiltration" or "burning"){FailLedger("You broke the Ledger's contract. Their stores close and the city faction becomes hostile.");return;}
  else{game.Notice="Complete the current objective first.";return;}game.Notice=Ledger.Outcome;game.Persist();
 }
 void WarnLedgerTarget(int i){if(Ledger.Target!=i||Ledger.State is not ("assault" or "infiltration")||Ledger.Burning)return;var t=Town(i);if(!PaySettlementCost(8,8,20,12,2))return;Ledger.Warned=true;Ledger.WaterSabotaged=false;t.Food+=8;t.Water+=8;t.WaterFixed=true;t.Foundation="fortify";t.Development=3;t.Policy="commons";t.StoryStage=4;t.StoryDue=0;t.StoryResult="You exposed the extermination order and reinforced our homes. The convoy escaped. We will trade our best relief equipment with you.";RememberTown(i,30,t.StoryResult);FailLedger("You warned the intended victims and paid for their defenses. They survive, and the Ledger sends its retaliation to your camp instead.");}
 void TickSettlementCampaigns(double dt){bool changed=false;foreach(var t in game.World.Changes.Settlements){t.MarketStock??=new[]{2,1,1,1};if(t.Index>=3||t.Fallen||t.StoryStage is 0 or 4||t.StoryDue<=0||game.World.Changes.Time<t.StoryDue)continue;if(t.StoryStage==1){t.DeadResidents|=8;AdvanceSettlement(t,2,0,ScoutName(t.Index)+" died waiting for help. A supply run became an empty place at the table.");}else{AdvanceSettlement(t,4,-1,"The rebuilding deadline passed. Materials rotted and the work crew scattered. This settlement's advanced market is lost.");t.Policy="decline";}changed=true;}
  if(Ledger.Due>0&&game.World.Changes.Time>=Ledger.Due&&Ledger.State is "debt" or "offer" or "assault" or "infiltration" or "burning"){FailLedger("You missed the Ledger's deadline. Voss marks you as a liability and orders retaliation.");changed=true;}
  SpawnSettlementSites();TickLedgerRaid(dt);if(changed)game.Persist();
 }
}
